import fs from 'node:fs'
import path from 'node:path'

const dir = path.join(process.cwd(), 'templates')
const files = {
  home: 'home.html',
  aanbod: 'aanbod.html',
  overOns: 'over-ons.html',
  itemProject: 'item-project.html',
  itemSlide: 'item-slide.html',
  itemService: 'item-service.html',
  itemMember: 'item-member.html',
}
const out = [
  '// GENERATED by scripts/gen-templates.mjs — do not edit by hand.',
  '// Source of truth: templates/*.html — verbatim Webflow markup with {{SLOT}} holes.',
  '',
]
for (const [key, file] of Object.entries(files)) {
  out.push(`export const ${key} = ${JSON.stringify(fs.readFileSync(path.join(dir, file), 'utf8'))}\n`)
}
fs.writeFileSync(path.join(process.cwd(), 'lib', 'templates.ts'), out.join('\n'))
console.log('lib/templates.ts written')
